<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getList, getPage, post, put } from '@/api/resources'
import { problemMessage } from '@/api/http'
import type { Activity, Announcement } from '@/types/domain'
import StatusTag from '@/components/StatusTag.vue'
import { formatDate } from '@/utils/format'

interface Tag { id: string; name: string; public?: boolean }
interface Reservation { id: string; reserveCode?: string; visitorName?: string; sessionTitle?: string; status: string; createdAt?: string }
const active = ref('announcements'); const loading = ref(false); const error = ref(''); const tags = ref<Tag[]>([]); const announcements = ref<Announcement[]>([]); const activities = ref<Activity[]>([]); const reservations = ref<Reservation[]>([]); const announcementDialog = ref(false); const activityDialog = ref(false); const submitting = ref(false); const announcement = reactive({ id: '', title: '', body: '', startsAt: '', endsAt: '', eventId: '' }); const activity = reactive({ id: '', title: '', description: '', location: '', status: 'Published' }); const session = reactive({ activityId: '', startsAt: '', endsAt: '', capacity: 30, status: 'Published' }); const tagName = ref('')
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const [tagData, noticeData, activityData, reservationData] = await Promise.all([getList<Tag>('/services/tags'), getPage<Announcement>('/services/announcements'), getPage<Activity>('/services/activities'), getPage<Reservation>('/services/reservations')]); tags.value = tagData; announcements.value = noticeData.items; activities.value = activityData.items; reservations.value = reservationData.items } catch (e) { error.value = problemMessage(e) } finally { loading.value = false } }
async function saveTag(): Promise<void> { if (!tagName.value.trim()) return; try { await post('/services/tags', { name: tagName.value.trim() }); tagName.value = ''; await load() } catch (e) { ElMessage.error(problemMessage(e)) } }
async function removeTag(tag: Tag): Promise<void> { try { await ElMessageBox.confirm(`删除标签“${tag.name}”？`, '确认删除', { type: 'warning' }); await import('@/api/http').then(({ http }) => http.delete(`/services/tags/${tag.id}`)); await load() } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error(problemMessage(e)) } }
function announcementPayload(): object { return { title: announcement.title, body: announcement.body, startsAt: announcement.startsAt || null, endsAt: announcement.endsAt || null, eventId: announcement.eventId || null } }
function editAnnouncement(item?: Announcement): void { Object.assign(announcement, { id: item?.id ?? '', title: item?.title ?? '', body: item?.body ?? '', startsAt: item?.startsAt ?? '', endsAt: item?.endsAt ?? '', eventId: item?.eventId ?? '' }); announcementDialog.value = true }
async function saveAnnouncement(): Promise<void> { if (!announcement.title || !announcement.body) return ElMessage.warning('请填写公告标题和正文。'); submitting.value = true; try { if (announcement.id) await put(`/services/announcements/${announcement.id}`, announcementPayload()); else await post('/services/announcements', announcementPayload()); announcementDialog.value = false; await load(); ElMessage.success('公告已保存。') } catch (e) { ElMessage.error(problemMessage(e)) } finally { submitting.value = false } }
async function publishAnnouncement(item: Announcement, publish: boolean): Promise<void> { try { await post(`/services/announcements/${item.id}/${publish ? 'publish' : 'withdraw'}`); await load(); ElMessage.success(publish ? '公告已发布。' : '公告已撤回。') } catch (e) { ElMessage.error(problemMessage(e)) } }
function editActivity(item?: Activity): void { Object.assign(activity, { id: item?.id ?? '', title: item?.title ?? '', description: item?.description ?? '', location: item?.location ?? '', status: item?.status ?? 'Published' }); activityDialog.value = true }
async function saveActivity(): Promise<void> { if (!activity.title || !activity.location) return ElMessage.warning('请填写活动名称和地点。'); submitting.value = true; try { if (activity.id) await put(`/services/activities/${activity.id}`, activity); else await post('/services/activities', activity); activityDialog.value = false; await load(); ElMessage.success('活动已保存。') } catch (e) { ElMessage.error(problemMessage(e)) } finally { submitting.value = false } }
async function addSession(): Promise<void> { if (!session.activityId || !session.startsAt || !session.endsAt) return ElMessage.warning('请选择活动并填写场次时间。'); try { await post(`/services/activities/${session.activityId}/sessions`, session); await load(); ElMessage.success('活动场次已新增。') } catch (e) { ElMessage.error(problemMessage(e)) } }
async function checkIn(item: Reservation): Promise<void> { try { await post(`/services/reservations/${item.id}/check-in`); await load(); ElMessage.success('预约已核销。') } catch (e) { ElMessage.error(problemMessage(e)) } }
onMounted(() => { void load() })
</script>
<template><div class="page"><div class="page-heading"><div><h1>智慧服务</h1><p>维护游客可见的标签、公告、活动场次与预约核销。</p></div><el-button v-if="active === 'announcements'" type="primary" @click="editAnnouncement()">新建公告</el-button><el-button v-else-if="active === 'activities'" type="primary" @click="editActivity()">新建活动</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="error" /><el-tabs v-model="active" class="service-tabs"><el-tab-pane label="标签管理" name="tags"><section class="surface tags-panel"><div class="tag-editor"><el-input v-model="tagName" placeholder="输入公园公开标签" @keyup.enter="saveTag" /><el-button type="primary" @click="saveTag">添加标签</el-button></div><div v-loading="loading" class="tag-cloud"><el-tag v-for="tag in tags" :key="tag.id" closable @close="removeTag(tag)">{{ tag.name }}</el-tag><el-empty v-if="!loading && !tags.length" description="暂无标签" /></div></section></el-tab-pane><el-tab-pane label="公告发布" name="announcements"><section class="surface table-panel"><el-table v-loading="loading" :data="announcements" empty-text="暂无公告"><el-table-column prop="title" label="标题" min-width="200" /><el-table-column prop="body" label="公开摘要" min-width="240" show-overflow-tooltip /><el-table-column label="生效区间" width="240"><template #default="scope">{{ formatDate(scope.row.startsAt) }} 至 {{ formatDate(scope.row.endsAt) }}</template></el-table-column><el-table-column label="状态" width="105"><template #default="scope"><StatusTag :status="scope.row.status || (scope.row.status === 'Published' ? 'Published' : 'Draft')" /></template></el-table-column><el-table-column label="操作" width="200" fixed="right"><template #default="scope"><el-button link type="primary" @click="editAnnouncement(scope.row)">编辑</el-button><el-button link :type="scope.row.status === 'Published' ? 'warning' : 'success'" @click="publishAnnouncement(scope.row, scope.row.status !== 'Published')">{{ scope.row.status === 'Published' ? '撤回' : '发布' }}</el-button></template></el-table-column></el-table></section></el-tab-pane><el-tab-pane label="活动与场次" name="activities"><div class="grid-2"><section class="surface table-panel"><el-table v-loading="loading" :data="activities" empty-text="暂无活动"><el-table-column prop="title" label="活动" min-width="150" /><el-table-column prop="location" label="地点" min-width="120" /><el-table-column label="场次" width="90"><template #default="scope">{{ scope.row.sessions?.length ?? 0 }}</template></el-table-column><el-table-column label="操作" width="90"><template #default="scope"><el-button link type="primary" @click="editActivity(scope.row)">编辑</el-button></template></el-table-column></el-table></section><section class="surface session-form"><div class="data-title">新增独立场次</div><p class="muted">容量、时间和发布状态由场次单独维护。</p><el-form label-position="top"><el-form-item label="活动"><el-select v-model="session.activityId"><el-option v-for="item in activities" :key="item.id" :label="item.title" :value="item.id" /></el-select></el-form-item><div class="form-row"><el-form-item label="开始"><el-date-picker v-model="session.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]" /></el-form-item><el-form-item label="结束"><el-date-picker v-model="session.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]" /></el-form-item></div><div class="form-row"><el-form-item label="容量"><el-input-number v-model="session.capacity" :min="1" /></el-form-item><el-form-item label="状态"><el-select v-model="session.status"><el-option label="草稿" value="Draft" /><el-option label="已发布" value="Published" /></el-select></el-form-item></div><el-button type="primary" @click="addSession">新增场次</el-button></el-form></section></div></el-tab-pane><el-tab-pane label="预约核销" name="reservations"><section class="surface table-panel"><el-table v-loading="loading" :data="reservations" empty-text="暂无预约"><el-table-column prop="reserveCode" label="预约码" min-width="135" /><el-table-column prop="visitorName" label="游客" width="130" /><el-table-column prop="sessionTitle" label="场次" min-width="180" /><el-table-column label="预约时间" width="175"><template #default="scope">{{ formatDate(scope.row.createdAt) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="scope"><StatusTag :status="scope.row.status" /></template></el-table-column><el-table-column label="操作" width="100"><template #default="scope"><el-button link type="primary" :disabled="scope.row.status !== 'Reserved'" @click="checkIn(scope.row)">核销入场</el-button></template></el-table-column></el-table></section></el-tab-pane></el-tabs><el-dialog v-model="announcementDialog" :title="announcement.id ? '编辑公告' : '新建公告'" width="580px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="announcement.title" /></el-form-item><el-form-item label="正文"><el-input v-model="announcement.body" type="textarea" :rows="5" /></el-form-item><div class="form-row"><el-form-item label="开始时间"><el-date-picker v-model="announcement.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]" /></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="announcement.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]" /></el-form-item></div></el-form><template #footer><el-button @click="announcementDialog = false">取消</el-button><el-button type="primary" :loading="submitting" @click="saveAnnouncement">保存</el-button></template></el-dialog><el-dialog v-model="activityDialog" :title="activity.id ? '编辑活动' : '新建活动'" width="580px"><el-form label-position="top"><el-form-item label="活动名称"><el-input v-model="activity.title" /></el-form-item><el-form-item label="活动描述"><el-input v-model="activity.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="举办地点"><el-input v-model="activity.location" /></el-form-item></el-form><template #footer><el-button @click="activityDialog = false">取消</el-button><el-button type="primary" :loading="submitting" @click="saveActivity">保存</el-button></template></el-dialog></div></template>
<style scoped>.error { margin-bottom:14px; }.tags-panel,.table-panel,.session-form { padding:18px; }.tag-editor { display:flex; gap:10px; width:420px; }.tag-cloud { display:flex; flex-wrap:wrap; min-height:130px; gap:10px; margin-top:24px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; }</style>
